{"command":"kubectl get deployment app -n default -o json 2>/dev/null | python3 -c '
import sys, json
data = json.load(sys.stdin)
# Remove readOnlyRootFilesystem from container securityContext if it exists
if "spec" in data and "template" in data["spec"] and "containers" in data["spec"]["template"]["spec"]:
    for container in data["spec"]["template"]["spec"]["containers"]:
        if "securityContext" in container and "readOnlyRootFilesystem" in container["securityContext"]:
            del container["securityContext"]["readOnlyRootFilesystem"]
            # If securityContext becomes empty, remove it
            if not container["securityContext"]:
                del container["securityContext"]
print(json.dumps(data, indent=2))
' > /tmp/fix-deploy.json && echo "Fixed deployment JSON created""}

